// The Uncertain Archive as it floats on the sea.
// src/data/archive.json is generated by `npm run build:archive` from STARS/data.
// predictions stay null until real inference runs — null means "not yet read",
// never "unrelated". Every star stays on the sea whatever its scores are.

import archiveData from './data/archive.json';
import { scatter } from './layout.js';
import { combinedScore, starScoreOf, agreementLabel, CATEGORIES } from './inference/scoring.js';

// Cached machine readings written by `npm run analyze` (empty until it has run).
const cached = Object.values(import.meta.glob('./data/predictions.json', { eager: true, import: 'default' }))[0]?.stars ?? {};

// Vite resolves each compressed image in /Pic to a servable URL (dev and build).
const imageURLs = import.meta.glob('/Pic/*.webp', { eager: true, query: '?url', import: 'default' });
const thumbURLs = import.meta.glob('/Pic/thumb/*.webp', { eager: true, query: '?url', import: 'default' });

export const MODEL_KEYS = ['tm', 'clip', 'mn'];

// Positions come from src/layout.js (density is tuned in config.js → LAYOUT).
const positions = scatter(archiveData.stars.length);
export const initialArchive = archiveData.stars.map((star, i) => ({
  ...star,
  image: imageURLs[`/Pic/${star.image}`] ?? null,
  thumb: thumbURLs[`/Pic/${star.thumb}`] ?? null,      // square image wrapped onto the 3D star
  position: positions[i],
  ...(cached[star.id] ? { predictions: cached[star.id].predictions, analysisStatus: cached[star.id].analysisStatus, modelVersion: cached[star.id].modelVersion } : {})
}));

export function newArchiveItem({ id, image, title, x, z }) {
  return {
    id: id ?? `upload_${Date.now().toString(36)}`,
    image,
    thumb: image,
    color: null,
    title,
    humanCategories: [],
    originalFile: null,
    source: null,
    position: { x, z },
    analysisStatus: 'pending',
    predictions: { tm: null, clip: null, mn: null },
    uploaded: true
  };
}

// One model's Star-relatedness (0–1), or null when that model has not spoken
// or could not recognise the object.
export const modelScore = (item, key) => starScoreOf(item.predictions?.[key]);

// Weighted mean of the models that have a reading (config.js → MODELS.weights);
// null when the star is still unresolved.
export const relatedness = (item) => combinedScore(item.predictions);

// Poetic line for the Polaroid. It speaks about the image, not about the machines.
export function quoteFor(item) {
  const p = item.predictions, score = relatedness(item);
  if (score === null || item.analysisStatus === 'uncertain') return 'Some stars have yet to be named.';
  if (agreementLabel(p) === 'disagree') return 'The same light can tell different stories.';
  if (score < .3) return 'Not everything that matters has to shine.';
  if (p.tm?.top === 'Represented' || p.clip?.top === 'Represented') return 'Some names are known. Others are loved.';
  if (score > .8 && (p.tm?.top === 'Direct' || p.clip?.top === 'Direct')) return 'Some stars are exactly where we expect them.';
  return "Everything belongs to someone's constellation.";
}

// Small hover text for each bar on the Polaroid.
export function readingDetail(item, key) {
  const p = item.predictions?.[key];
  const pct = v => `${Math.round(v * 100)}%`;
  if (key === 'tm') return p ? `Teachable Machine · ${pct(p.starScore)} · leans ${p.top}\n(trained on this archive, so it has seen many of these images)` : 'Teachable Machine · not yet read';
  if (key === 'clip') return p ? `CLIP · ${pct(p.starScore)} · leans ${p.top}` : 'CLIP · not yet read';
  if (!p) return 'MobileNet · not yet read';
  const seen = p.labels.map(l => l.label.split(',')[0]).join(', ');
  return p.matched ? `MobileNet · ${pct(p.starScore)} · sees ${seen}` : `MobileNet sees ${seen} — none of it is in the star vocabulary, so it stays unnamed`;
}

export { CATEGORIES };

const LICENSES = { by: 'CC BY', 'by-sa': 'CC BY-SA', 'by-nc': 'CC BY-NC', 'by-nc-sa': 'CC BY-NC-SA', 'by-nd': 'CC BY-ND', 'by-nc-nd': 'CC BY-NC-ND', cc0: 'CC0', pdm: 'Public Domain' };
export function creditFor(item) {
  const s = item.source;
  if (!s?.creator) return null;
  return { text: `Photo · ${s.creator}${s.license ? ' · ' + (LICENSES[s.license] ?? s.license) : ''}`, href: s.page };
}
